def parse_rules(rules_file):
    rules = OrderedDict()
    with open(rules_file, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            try:
                name, expr = stripped.split('=', 1)
                rules[name] = expr
            except ValueError:
                continue
    return rules

def evaluate_expression(expr, a, b, c):
    try:
        # Replace variables with values
        expr = expr.replace('a', str(a))
        expr = expr.replace('b', str(b))
        expr = expr.replace('c', str(c))

        # Define operator functions
        ops = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow,
        }

        # Replace operators with their corresponding functions
        for op, func in ops.items():
            expr = expr.replace(op, f'lambda x, y: {func.__name__}(x, y)')

        # Handle unary minus
        expr = re.sub(r'^-(\d+)', lambda m: f'lambda x: {m.group(1)} * -1', expr)
        expr = re.sub(r'^-([a-zA-Z_]\w*)', lambda m: f'lambda x: {m.group(1)} * -1', expr)

        # Evaluate the expression
        def eval_expr(e):
            try:
                return eval(e)
            except Exception as e:
                raise ValueError(f"Evaluation error: {str(e)}")

        # Use a safe eval with a restricted namespace
        namespace = {
            'a': a,
            'b': b,
            'c': c,
        }
        return eval_expr(expr)
    except Exception as e:
        raise ValueError(f"Expression evaluation error: {str(e)}")

def process_input(rules, input_line, line_num):
    try:
        data = json.loads(input_line)
        if 'a' not in data or 'b' not in data or 'c' not in data:
            raise ValueError("Missing required keys 'a', 'b', or 'c'")

        a, b, c = data['a'], data['b'], data['c']
        result = {}
        for name in rules:
