import argparse
import json
import sys
import hashlib
from collections import OrderedDict
from typing import Dict, List, Any, Optional

def parse_rules(rules_file: str) -> OrderedDict[str, str]:
    rules = OrderedDict()
    with open(rules_file, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' not in line:
                raise ValueError(f"Invalid rule format in line {line_num}: {line}")
            name, expr = line.split('=', 1)
            name = name.strip()
            if not name or not name.isidentifier() or name[0].isdigit():
                raise ValueError(f"Invalid rule name '{name}' in line {line_num}")
            rules[name] = expr.strip()
    return rules

def evaluate_expression(expr: str, a: float, b: float, c: float) -> float:
    try:
        return eval(expr, {'__builtins__': None}, {'a': a, 'b': b, 'c': c})
    except Exception as e:
        raise ValueError(f"Expression evaluation error: {str(e)}")

def process_input(input_lines: List[str], rules: OrderedDict[str, str]) -> List[Dict[str, Any]]:
    results = []
